# Body Types & MAOP Function
# ------------------------------------------------------------------------------------------------------

def body_type121(reg):
    suf = reg[-2:]
    if suf == "13":
        return '3/4" or 1"'
    elif suf == "10":
        return '1"'
    elif suf == "1Q":
        return '1-1/4"'
    elif suf == "1H":
        return '1-1/2"'
    elif suf == "20":
        return '2"'
    elif suf == "2H":
        return '2-1/2"'
    elif suf == "30":
        return '3"'
    return "Unknown"

def body_max121(reg):
    pre = reg[:6]
    suf = reg[-2:]
    if pre == 'R12208' or pre == 'R12212':
        return 15
    elif suf == '30':
        return 40
    else:
        return 60


